package com.loanops.fincompass.opportunity;
import com.loanops.fincompass.matching.*;import com.loanops.fincompass.simulation.*;import com.loanops.fincompass.twin.*;import com.loanops.personal.canonical.*;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.math.BigDecimal;import java.time.Clock;import static com.loanops.fincompass.opportunity.OpportunityModels.*;
@Configuration(proxyBeanMethods=false) @ConditionalOnProperty(name="fincompass.personal.enabled",havingValue="true") public class OpportunityConfiguration {
 @Bean OpportunityEngine opportunityEngine(){return new OpportunityEngine();}@Bean Policy opportunityPolicy(@Value("${fincompass.opportunity.emergency-fund-months:3}")BigDecimal emergency,@Value("${fincompass.opportunity.debt-burden-threshold:0.40}")BigDecimal burden,@Value("${fincompass.opportunity.refinancing-rate-gap:0.01}")BigDecimal gap,@Value("${fincompass.opportunity.rule-version:OPPORTUNITY_V1}")String version){return new Policy(emergency,burden,gap,version);}
 @Bean OpportunityStore opportunityStore(JdbcTemplate jdbc,PersonalFinanceCipher cipher,FinancialTwinStore twins,PlatformTransactionManager manager){return new OpportunityStore(jdbc,cipher,twins,manager);}@Bean OpportunityService opportunityService(OpportunityStore store,OpportunityEngine engine,FinancialTwinStore twins,ScenarioService scenarios,MatchService matches,Policy policy,ObjectProvider<Clock> clocks){return new OpportunityService(store,engine,twins,scenarios,matches,policy,clocks.getIfAvailable(Clock::systemUTC));}}
